mapper.select:
SELECT answer_id, exam_id, student_id, question_id, student_response, is_graded, obtained_score, grader_id, grade_time, save_time, extra_info
FROM student_answer
WHERE exam_id = #{examId} AND student_id = #{studentId}

SELECT answer_id, exam_id, student_id, question_id, student_response, is_graded, obtained_score, grader_id, grade_time, save_time, extra_info
FROM student_answer
WHERE exam_id = #{examId} AND student_id = #{studentId} AND question_id = #{questionId}

SELECT sa.answer_id, sa.exam_id, sa.student_id, sa.question_id, sa.student_response, sa.is_graded, sa.obtained_score, sa.grader_id, sa.grade_time, sa.save_time, sa.extra_info, q.question_id AS q_id, q.question_type, q.difficulty, q.content, q.options, q.answer, q.default_score, pq.question_score FROM student_answer sa LEFT JOIN question q ON sa.question_id = q.question_id LEFT JOIN exam e ON sa.exam_id = e.exam_id LEFT JOIN paper_question pq ON pq.paper_id = e.paper_id AND pq.question_id = sa.question_id WHERE (sa.is_graded = 0 OR sa.is_graded IS NULL)
AND sa.exam_id = #{examId}
ORDER BY sa.save_time DESC
